  sizeDefault: { en: 'Default (1.0x)', hi: 'सामान्य (1.0x)', mr: 'सामान्य (1.0x)', gu: 'સામાન્ય (1.0x)', bn: 'ডিফল্ট (1.0x)', ta: 'இயல்புநிலை (1.0x)', te: 'సాధారణం (1.0x)', kn: 'ಸಾಮಾನ್ಯ (1.0x)', ml: 'സാധാരണ (1.0x)', pa: 'ਸਧਾਰਨ (1.0x)', or: 'ସାଧାରଣ (1.0x)' },
